#ifndef MEP_GO_LSP_VOCAB_H
#define MEP_GO_LSP_VOCAB_H

// The Go standard library's vocabulary for mep-go-lsp: every importable
// package and its exported consts, vars, funcs, types, methods and fields,
// with signatures and documentation. The table (go_lsp_vocab_data.cpp) is
// generated by tools/gen_go_vocab.go (`just go-lsp-vocab`) with go/doc from
// the Go source tree; the docs are Go's own (BSD, notice in that file).

#include <cstddef>
#include <string>
#include <string_view>
#include <vector>

enum class GoVocabKind : char { Package = 'p', Func = 'f', Method = 'm', Type = 't', Const = 'c', Var = 'v', Field = 'F' };

struct GoVocabEntry {
    const char *pkg;   // import path: "net/http"; "builtin" for the predeclared names
    const char *name;  // "" for the package itself, "Get", "Client.Do", "Request.Method"
    GoVocabKind kind;
    const char *signature;  // the declaration as go/printer prints it, bodies dropped
    const char *doc;        // plain text, capped at a paragraph boundary
    bool deprecated;        // has a "Deprecated:" paragraph
};

/** @brief The entry for `name` in package `pkg` (name "" = the package), or nullptr. */
const GoVocabEntry *GoVocabFind(std::string_view pkg, std::string_view name);
/** @brief A package's top-level members (no methods or fields), sorted by name. */
std::vector<const GoVocabEntry *> GoVocabMembers(std::string_view pkg);
/** @brief A type's methods and fields ("T.X" entries), sorted by name. */
std::vector<const GoVocabEntry *> GoVocabTypeMembers(std::string_view pkg, std::string_view type);
/** @brief Every import path in the table, sorted. */
const std::vector<std::string_view> &GoVocabPackages();
/** @brief Number of entries. */
size_t GoVocabSize();

#endif
